import (
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsPath 是阈值配置文件的路径。默认按本文件所在位置解析到仓库根的
// config/thresholds.json，因此断言不受当前工作目录影响。
var thresholdsPath = defaultThresholdsPath()

func defaultThresholdsPath() string {
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		return filepath.Join("config", "thresholds.json")
	}
	return filepath.Join(filepath.Dir(file), "..", "config", "thresholds.json")
}

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 仓库在 config/thresholds.json 里配了就用自己的阈值；未配置、文件不存在、读不出来
// 或内容不是 JSON 对象时，一律回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, ok := loadThresholds()
	if !ok {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取阈值配置。任何读取或解析失败都返回 ok=false，由调用方回退默认值。
func loadThresholds() (map[string]int, bool) {
	data, err := os.ReadFile(thresholdsPath)
	if err != nil {
		return nil, false
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, false
	}
	return thresholds, true
}

